// ตรวจ event จากเว็บ/app + ด่านความยินยอม (consent-gated) + แปลงชื่อ event ให้ตรงกับ /api/track
// ด่าน ① Consent: ไม่มีความยินยอม = ไม่บันทึกอะไรเลย
// รองรับ 2 ทาง: สคริปต์เว็บยิงตรงเข้า n8n หรือแอป /api/track ส่งต่อมา (ผ่าน N8N_WEBHOOK_BASE)
const ALIASES = { session_start: 'session_start', video_start: 'video_view', video_25: 'video_progress', video_50: 'video_progress', video_75: 'video_progress', button_click: 'cta_click' };
const ALLOWED = ['page_view', 'return_visit', 'video_view', 'video_progress', 'video_complete', 'form_open', 'form_submit', 'topic_select', 'callback_request', 'cta_click', 'session_start'];
const canonical = function (raw) {
  const t = String(raw || '').toLowerCase().trim();
  if (ALIASES[t]) return ALIASES[t];
  return ALLOWED.indexOf(t) !== -1 ? t : null;
};
const str = function (v, max) { return (v === undefined || v === null || v === '') ? null : String(v).slice(0, max || 500); };
const num = function (v) { const x = Number(v); return Number.isFinite(x) ? x : 0; };

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};
  const expected = String($env.TRACK_WEBHOOK_SECRET || '');
  const got = String(headers['x-track-secret'] || headers['X-Track-Secret'] || '');
  const secretOk = expected ? got === expected : true; // ยังไม่ตั้ง env = โหมด dev

  // consent — รับทุกรูปแบบเดียวกับฝั่งแอป (true / 'granted' / {analytics|tracking|status})
  const c = body.consent;
  let analytics = false, marketing = false, version = '1.0';
  if (c === true) analytics = true;
  else if (typeof c === 'string') analytics = c.toLowerCase() === 'granted';
  else if (c && typeof c === 'object') {
    analytics = c.analytics === true || c.tracking === true || c.status === 'granted' || c.analyticsConsent === true;
    marketing = c.marketing === true;
    version = str(c.version, 20) || '1.0';
  } else analytics = body.analyticsConsent === true;

  // UTM: รองรับทั้งแบบแบน (utmSource) และแบบ object (utm:{source,medium,...}) เหมือนฝั่งแอป
  const u = (body.utm && typeof body.utm === 'object') ? body.utm : {};
  const fb = {
    pageUrl: str(body.pageUrl || body.url, 2000),
    pagePath: str(body.pagePath || body.path, 500),
    referrer: str(body.referrer, 2000),
    utmSource: str(body.utmSource || body.utm_source || u.source, 200),
    utmMedium: str(body.utmMedium || body.utm_medium || u.medium, 200),
    utmCampaign: str(body.utmCampaign || body.utm_campaign || u.campaign, 200),
    utmTerm: str(body.utmTerm || body.utm_term || u.term, 200),
    utmContent: str(body.utmContent || body.utm_content || u.content, 200)
  };

  const rawList = (Array.isArray(body.events) && body.events.length) ? body.events : [body];
  const events = [];
  for (const raw of rawList.slice(0, 25)) {
    const src = (raw && typeof raw === 'object') ? raw : {};
    const type = canonical(src.type || src.event);
    if (!type) continue; // type ที่ไม่รู้จัก → ทิ้ง ไม่ทำให้ทั้ง request ล้ม
    const atRaw = src.at || src.timestamp || src.ts;
    const at = atRaw ? new Date(atRaw) : new Date();
    events.push({
      eventId: str(src.eventId, 64), // ส่ง eventId เดิมกลับไป → แอปกันซ้ำด้วย unique eventId (ไม่นับคะแนนซ้ำ)
      type: type,
      at: Number.isNaN(at.getTime()) ? new Date().toISOString() : at.toISOString(),
      pageUrl: str(src.pageUrl || src.url, 2000) || fb.pageUrl,
      pagePath: str(src.pagePath || src.path, 500) || fb.pagePath,
      referrer: str(src.referrer, 2000) || fb.referrer,
      utmSource: str(src.utmSource || src.utm_source, 200) || fb.utmSource,
      utmMedium: str(src.utmMedium || src.utm_medium, 200) || fb.utmMedium,
      utmCampaign: str(src.utmCampaign || src.utm_campaign, 200) || fb.utmCampaign,
      videoCode: str(src.videoCode || src.video_id || src.video, 64),
      videoId: str(src.videoUuid, 64),
      watchPct: Math.min(100, Math.max(0, num(src.watchPct || src.watch_pct))),
      watchSeconds: num(src.watchSeconds || src.watch_seconds) || null,
      meta: (src.meta && typeof src.meta === 'object') ? src.meta : undefined
    });
  }

  const valid = secretOk && analytics && events.length > 0;
  const reason = !secretOk ? 'secret ของ webhook ไม่ถูกต้อง'
    : !analytics ? 'ยังไม่ได้รับความยินยอม (consent) จึงไม่บันทึก'
    : 'ไม่พบ event ที่รู้จักใน payload';
  out.push({ json: {
    valid: valid, reason: valid ? null : reason,
    visitorId: str(body.visitorId, 64), sessionId: str(body.sessionId, 64), prospectId: str(body.prospectId, 64),
    consent: { analytics: analytics, marketing: marketing, version: version },
    device: str(body.device, 40), browser: str(body.browser, 40),
    utm: { source: fb.utmSource, medium: fb.utmMedium, campaign: fb.utmCampaign, content: fb.utmContent, term: fb.utmTerm },
    events: events, eventCount: events.length, firstType: events.length ? events[0].type : null,
    at: new Date().toISOString()
  } });
}
return out;

// ประเมินผลจาก /api/track (รวมกรณี event ซ้ำที่แอปบันทึกไว้แล้ว)
const res = $('บันทึก Visitor + Event (/api/track)').first().json || {};
const src = $('ตรวจสอบข้อมูล + ด่านความยินยอม (Validate)').first().json || {};
const status = res.statusCode === undefined ? null : Number(res.statusCode);
const ok = res.ok === true && (status === null || (status >= 200 && status < 300));
const stored = Number(res.stored || 0), dup = Number(res.duplicates || 0);
const detail = ok
  ? 'บันทึก ' + stored + ' event' + (dup ? ' (ซ้ำ ' + dup + ' — ไม่นับคะแนน)' : '')
    + (res.score === null || res.score === undefined ? '' : ' | คะแนน ' + res.score + ' (' + (res.level || '-') + ')')
  : String(res.error || res.message || ('HTTP ' + (status === null ? 'ไม่ตอบสนอง' : status))).slice(0, 300);
return [{ json: {
  ok: ok, workflow: '01-visitor-tracking', stage: 'store_event', detail: detail,
  statusCode: status, stored: stored, duplicates: dup, score: res.score, level: res.level,
  visitorId: res.visitorId || src.visitorId, eventType: src.firstType, eventCount: src.eventCount,
  alertText: ok
    ? 'Visitor Tracking ปกติ (บันทึก ' + stored + ' event)'
    : 'แจ้งเตือน: Visitor Tracking บันทึก event ไม่สำเร็จ — ' + detail,
  at: new Date().toISOString()
} }];
